<?php
namespace Semizzy\Addons\Education\Models;
use Illuminate\Database\Eloquent\Model;
final class EducationAdmissionRequirement extends Model { protected $table='education_admission_requirements'; protected $guarded=[]; protected $casts=['awaiting_result_allowed'=>'boolean','post_utme_required'=>'boolean','screening_required'=>'boolean','international_qualification_verification_required'=>'boolean','verified_at'=>'datetime']; public function programmeAdmission(){return $this->belongsTo(EducationProgrammeAdmission::class,'programme_admission_id');} public function route(){return $this->belongsTo(EducationAdmissionRoute::class,'admission_route_id');} public function olevel(){return $this->hasOne(EducationAdmissionOLevelRequirement::class,'admission_requirement_id');} public function utmeCombinations(){return $this->hasMany(EducationAdmissionUtmeCombination::class,'admission_requirement_id');} public function directEntryQualifications(){return $this->hasMany(EducationAdmissionDirectEntryQualification::class,'admission_requirement_id');} public function resultBodies(){return $this->hasMany(EducationAdmissionResultBody::class,'admission_requirement_id');} public function sources(){return $this->hasMany(EducationAdmissionSource::class,'admission_requirement_id');}}
